window.AP_LEARNING=window.AP_LEARNING||{};
window.AP_LEARNING["lesson-14"]={
  version:1,title:"The Cardiovascular Circulatory System",chapter:14,duration:"80–100 minutes",
  outcomes:["Trace blood through the chambers, valves, lungs, and systemic circulation.","Relate the layers of the heart and vessels to their functions.","Sequence the cardiac conduction pathway and connect it to contraction.","Differentiate arteries, veins, and capillaries by structure and direction of flow.","Explain how cardiac output, resistance, and vessel tone support tissue perfusion without offering medical treatment."],
  modules:[
    {id:"heart-structure",title:"Build the heart as a pump",summary:"Learn the coverings, wall layers, chambers, valves, and great vessels as one connected design.",moments:[
      {id:"l14-m1",title:"The heart wall and its coverings have distinct jobs",highYield:"Pericardium contains and protects; myocardium contracts; endocardium lines the chambers and valves.",teaching:["The heart sits within a pericardial sac that limits friction and helps contain the organ. The wall itself includes an outer epicardial surface, a thick myocardium, and a smooth endocardial lining. The myocardium is thickest where the pressure demand is greatest, especially in the left ventricle.","Layer names are easiest to learn by asking what touches what. The endocardium touches blood, myocardium produces force, and the outer surface meets the pericardial space. Inflammation or damage in one layer is not automatically equivalent to disease in another."],keyPoints:["The pericardium surrounds the heart.","Myocardium is cardiac muscle.","Endocardium lines chambers and valves.","Left ventricular myocardium is especially thick."],visual:{title:"Heart from outside to inside",kind:"layers",items:[{label:"Fibrous/serous pericardium",detail:"Protective sac and low-friction surfaces"},{label:"Epicardium",detail:"Outer heart-wall layer"},{label:"Myocardium",detail:"Contractile cardiac muscle"},{label:"Endocardium",detail:"Smooth inner lining"}]},mnemonic:{title:"E-M-E",cue:"Epicardium · Myocardium · Endocardium",explanation:"Move from exterior to interior; myocardium in the middle makes the movement."},goodToKnow:"The wall of the left ventricle is thicker because it must generate pressure for systemic circulation, not because it contains more blood.",practiceConnection:"Use layer-specific language when explaining a report; do not use 'heart problem' as though all tissues and mechanisms were the same.",activity:{prompt:"Which layer generates the force that ejects blood?",options:[{text:"Myocardium",correct:true,feedback:"Correct. Cardiac muscle in the myocardium contracts."},{text:"Endocardium",correct:false,feedback:"The endocardium is the inner lining."},{text:"Parietal pericardium",correct:false,feedback:"The pericardium surrounds the heart but does not pump blood."}]}},
      {id:"l14-m2",title:"Four chambers create two coordinated pumps",highYield:"The right side sends blood to the lungs; the left side sends blood to the body.",teaching:["The atria receive blood and the ventricles eject it. The right atrium receives systemic venous blood, and the right ventricle sends it through the pulmonary trunk toward the lungs. Pulmonary veins return oxygenated blood to the left atrium, and the left ventricle ejects it into the aorta.","Septa separate the right and left sides, while valves support one-way movement. The tricuspid and mitral valves lie between atria and ventricles; the pulmonary and aortic semilunar valves guard ventricular outflow. Valves open and close because pressure gradients change, not because they actively pull themselves open."],keyPoints:["Atria receive; ventricles eject.","Right heart supports pulmonary flow.","Left heart supports systemic flow.","Pressure differences operate the valves."],visual:{title:"Chambers and valves",kind:"flow",items:[{label:"Right atrium",detail:"Receives vena-caval and coronary venous return"},{label:"Tricuspid valve",detail:"Directs flow to right ventricle"},{label:"Pulmonary valve",detail:"Directs flow to pulmonary trunk"},{label:"Left atrium",detail:"Receives pulmonary venous return"},{label:"Mitral and aortic valves",detail:"Direct flow through left ventricle into aorta"}]},mnemonic:{title:"A-V-E",cue:"Atrium receives · Ventricle pumps · Exit through semilunar valve",explanation:"Use AVE on both sides of the heart."},goodToKnow:"Pulmonary arteries carry deoxygenated blood and pulmonary veins carry oxygenated blood; artery and vein are defined by direction relative to the heart.",practiceConnection:"When reading a diagram, follow direction and valve order rather than relying only on red and blue colours, which are conventions.",activity:{prompt:"What directly causes a normal heart valve to open?",options:[{text:"A pressure difference across the valve",correct:true,feedback:"Correct. Flow follows the pressure gradient and moves the valve leaflets."},{text:"A valve-specific nerve pulling it open",correct:false,feedback:"Valves operate passively through pressure changes."},{text:"The colour of the blood",correct:false,feedback:"Diagram colours do not control physiology."}]}}
    ]},
    {id:"flow-rhythm",title:"Follow flow and electrical timing",summary:"Connect circulation order, conduction, and the mechanical cardiac cycle.",moments:[
      {id:"l14-m3",title:"Trace one complete circuit without skipping the lungs",highYield:"Systemic return → right heart → lungs → left heart → systemic arteries.",teaching:["A complete trace begins with systemic veins entering the venae cavae, then passes through the right atrium, tricuspid valve, right ventricle, pulmonary valve, pulmonary trunk, and pulmonary arteries. Gas exchange occurs in lung capillaries before pulmonary veins return blood to the left atrium.","Blood then crosses the mitral valve into the left ventricle, passes the aortic valve, and enters the aorta. Coronary arteries branch near the aortic root to supply the heart itself. Remember that the two pumps work in series: sustained output from one side must be matched by the other."],keyPoints:["Pulmonary circulation links right and left heart.","Systemic circulation begins at the aorta.","Coronary circulation supplies myocardium.","The two sides pump the same long-term volume."],visual:{title:"One red-cell journey",kind:"sequence",items:[{label:"Systemic veins",detail:"Return blood to venae cavae"},{label:"Right heart",detail:"Receives and sends blood to lungs"},{label:"Lung capillaries",detail:"Exchange oxygen and carbon dioxide"},{label:"Left heart",detail:"Receives and sends blood to aorta"},{label:"Systemic capillaries",detail:"Exchange with tissues"}]},mnemonic:{title:"Body–Right–Lungs–Left–Body",cue:"BRLLB",explanation:"Say the five locations before adding chambers and valves."},goodToKnow:"Oxygenation changes in capillary beds; it does not occur simply because blood enters an artery or vein.",practiceConnection:"This flow map helps explain why breathlessness, edema, or chest symptoms require assessment rather than a food-only explanation.",activity:{prompt:"Which vessel returns oxygenated blood from the lungs?",options:[{text:"Pulmonary veins",correct:true,feedback:"Correct. They enter the left atrium."},{text:"Pulmonary arteries",correct:false,feedback:"Pulmonary arteries carry blood from the right ventricle toward the lungs."},{text:"Superior vena cava",correct:false,feedback:"It returns systemic venous blood to the right atrium."}]}},
      {id:"l14-m4",title:"Electrical conduction coordinates contraction",highYield:"SA node initiates, AV node delays, and the ventricular conduction network distributes the impulse.",teaching:["Autorhythmic cells can generate electrical activity without a motor nerve initiating every beat. The sinoatrial node normally sets the rhythm across the atria. The atrioventricular node briefly delays conduction, allowing atrial emptying before the impulse travels into the atrioventricular bundle.","Bundle branches and Purkinje fibres distribute activation through ventricular myocardium so contraction proceeds efficiently. Electrical activity and mechanical contraction are linked but not identical; an electrocardiogram records surface electrical patterns, not the pumping force itself."],keyPoints:["SA node is the usual pacemaker.","AV delay supports filling.","Bundle branches and Purkinje fibres activate ventricles.","ECG reflects electrical, not direct mechanical, activity."],visual:{title:"Conduction pathway",kind:"flow",items:[{label:"SA node",detail:"Initiates atrial depolarization"},{label:"AV node",detail:"Brief delay"},{label:"AV bundle",detail:"Only normal electrical bridge through fibrous skeleton"},{label:"Bundle branches",detail:"Travel through interventricular septum"},{label:"Purkinje network",detail:"Distributes activation through ventricles"}]},mnemonic:{title:"Start–Await–Bundle–Branch–Purkinje",cue:"S-A-B-B-P",explanation:"The sequence mirrors the path from pacemaker to ventricular muscle."},goodToKnow:"Autonomic nerves change heart rate and force, but the intrinsic conduction system organizes the beat.",practiceConnection:"Palpitations or an abnormal rhythm report should be referred for clinical assessment; a nutrition discussion cannot determine the rhythm mechanism.",activity:{prompt:"Why is the AV nodal delay useful?",options:[{text:"It gives the atria time to complete emptying before ventricular contraction",correct:true,feedback:"Correct. Timing supports efficient sequential pumping."},{text:"It oxygenates blood inside the node",correct:false,feedback:"Gas exchange occurs mainly in capillaries, not the AV node."},{text:"It closes every blood vessel",correct:false,feedback:"The AV node coordinates electrical timing, not vessel closure."}]}}
    ]},
    {id:"cycle-vessels",title:"Connect the cardiac cycle to vessels",summary:"Distinguish systole, diastole, vessel walls, and capillary exchange.",moments:[
      {id:"l14-m5",title:"Systole and diastole describe changing pressure phases",highYield:"Filling and ejection depend on pressure gradients created by relaxation and contraction.",teaching:["During ventricular diastole, ventricular pressure falls and the atrioventricular valves open when atrial pressure is higher. Ventricular filling is mostly passive, with atrial contraction adding the final portion. During ventricular systole, pressure rises, atrioventricular valves close, and semilunar valves open once ventricular pressure exceeds arterial pressure.","Heart sounds are associated mainly with valve closure and surrounding vibration. Stroke volume is the amount ejected per beat, while cardiac output is heart rate multiplied by stroke volume. These values change with activity and physiological demand rather than remaining fixed at one ideal number."],keyPoints:["Diastole supports filling.","Systole supports ejection.","Valves respond to pressure gradients.","Cardiac output = heart rate × stroke volume."],visual:{title:"Cycle logic",kind:"comparison",items:[{label:"Diastole",detail:"Ventricular relaxation and filling"},{label:"AV-valve closure",detail:"Beginning of ventricular systole"},{label:"Ejection",detail:"Semilunar valves open when ventricular pressure is higher"},{label:"Semilunar closure",detail:"Occurs as arterial pressure exceeds ventricular pressure"}]},mnemonic:{title:"D fills, S sends",cue:"Diastole fills · Systole sends",explanation:"A compact cue for the ventricular cycle."},goodToKnow:"Blood pressure and cardiac output are related but not equivalent; pressure also depends strongly on vessel resistance and arterial properties.",practiceConnection:"Exercise, sleep, hydration, medicines, illness, and measurement technique can influence pulse and pressure; interpret a pattern rather than one isolated reading.",activity:{prompt:"What is cardiac output?",options:[{text:"Heart rate multiplied by stroke volume",correct:true,feedback:"Correct. It estimates volume pumped per minute."},{text:"Systolic pressure minus diastolic pressure",correct:false,feedback:"That difference is pulse pressure."},{text:"The amount of blood in the entire body",correct:false,feedback:"Cardiac output is flow per unit time."}]}},
      {id:"l14-m6",title:"Vessel walls match pressure and exchange",highYield:"Arteries distribute under pressure, veins return with high capacitance, and capillaries optimize exchange.",teaching:["Arteries have a prominent smooth-muscle and elastic middle layer that tolerates and adjusts to pulsatile pressure. Veins operate at lower pressure, have thinner walls and larger lumens, and often use valves plus skeletal-muscle and respiratory pumps to support return to the heart.","Capillary walls are primarily a single endothelial layer with a basement membrane, minimizing diffusion distance. Their enormous total cross-sectional area slows flow and supports exchange. Arterioles provide major resistance control; venules collect blood from capillary beds."],keyPoints:["Arteries carry blood away from the heart.","Veins carry blood toward the heart.","Capillaries are exchange vessels.","Arterioles strongly influence local resistance."],visual:{title:"Vessel comparison",kind:"comparison",items:[{label:"Artery",detail:"Thick, elastic, muscular wall; higher pressure"},{label:"Vein",detail:"Larger lumen; lower pressure; valves in many regions"},{label:"Capillary",detail:"One-cell-thick exchange surface"},{label:"Arteriole",detail:"Adjustable resistance vessel"}]},mnemonic:{title:"Away–Return–Exchange",cue:"Artery away · Vein return · Capillary exchange",explanation:"Direction defines artery and vein; wall design supports the job."},goodToKnow:"A vessel carrying oxygen-poor blood can still be an artery if it carries blood away from the heart.",practiceConnection:"Long periods of immobility affect the muscle pump; movement advice must still reflect an individual's medical and mobility context.",activity:{prompt:"Which vessel is best designed for diffusion between blood and tissue?",options:[{text:"Capillary",correct:true,feedback:"Correct. Its thin wall and broad network support exchange."},{text:"Aorta",correct:false,feedback:"The aorta is designed for high-pressure distribution."},{text:"Vena cava",correct:false,feedback:"The vena cava is a large return vessel."}]}}
    ]},
    {id:"integration",title:"Think in routes and regulation",summary:"Use circulation routes and homeostatic reasoning in applied scenarios.",moments:[
      {id:"l14-m7",title:"Not every circuit follows the same itinerary",highYield:"Pulmonary, coronary, systemic, and portal routes serve different exchange needs.",teaching:["Pulmonary circulation moves blood between heart and lungs. Coronary circulation supplies the myocardium. Systemic circulation serves the rest of the body, while portal circulation sends blood through a second capillary bed before returning to the heart. The hepatic portal route carries nutrient-rich blood from digestive organs to the liver.","The liver can process, store, transform, or release absorbed substances before they enter the general circulation. This first-pass relationship is central to nutrient handling and many medicines. It does not mean all absorbed material is stored, nor that the liver 'detoxes' every exposure completely."],keyPoints:["Coronary circulation feeds the heart muscle.","Pulmonary circulation supports gas exchange.","Hepatic portal blood reaches the liver before systemic return.","Routes reflect the exchange task."],visual:{title:"Four circulation routes",kind:"map",items:[{label:"Pulmonary",detail:"Heart ↔ lungs"},{label:"Coronary",detail:"Aorta → myocardium → coronary sinus/right atrium"},{label:"Systemic",detail:"Left heart → body tissues → right heart"},{label:"Hepatic portal",detail:"Digestive capillaries → portal vein → liver sinusoids"}]},mnemonic:{title:"PCSH",cue:"Pulmonary · Coronary · Systemic · Hepatic portal",explanation:"Name the destination and purpose for each route."},goodToKnow:"Dietary lipids are initially routed largely through intestinal lymph rather than directly through the hepatic portal vein.",practiceConnection:"The portal route helps explain why digestion, liver function, and systemic nutrient availability are connected but not identical.",activity:{prompt:"Where does blood from most absorbed water-soluble nutrients travel first?",options:[{text:"Through the hepatic portal vein to the liver",correct:true,feedback:"Correct. The liver receives portal blood from digestive organs."},{text:"Directly from the intestine into the left ventricle",correct:false,feedback:"Venous return reaches the liver and then the right heart before systemic circulation."},{text:"Only into the coronary arteries",correct:false,feedback:"Coronary arteries supply the myocardium."}]}},
      {id:"l14-m8",title:"Perfusion depends on pump, pipes, and volume",highYield:"Tissue delivery reflects cardiac output, vessel resistance, circulating volume, and local control.",teaching:["Cardiovascular homeostasis is a coordinated problem. The heart provides flow, arteries distribute pressure, arterioles adjust resistance, capillaries exchange, and veins return volume. Nervous, endocrine, renal, and local tissue signals continually alter this system to match changing demand.","Population-level dietary patterns can influence long-term cardiovascular risk, but a single nutrient cannot explain an individual's pressure, symptoms, or disease. Accurate practice separates risk-factor education from diagnosis and recognizes urgent symptoms that need immediate medical assessment."],keyPoints:["Flow requires a pressure gradient.","Resistance changes strongly with vessel radius.","Kidneys influence long-term volume and pressure.","Risk education is not acute symptom assessment."],visual:{title:"Perfusion model",kind:"map",items:[{label:"Pump",detail:"Heart rate and stroke volume"},{label:"Pipes",detail:"Vessel radius and elasticity"},{label:"Volume",detail:"Blood and extracellular-fluid regulation"},{label:"Demand",detail:"Local metabolic control in tissues"}]},mnemonic:{title:"PPVD",cue:"Pump · Pipes · Volume · Demand",explanation:"Use all four before explaining tissue perfusion."},goodToKnow:"Sodium affects extracellular-fluid regulation, but pressure response varies and cannot be inferred from one meal.",practiceConnection:"Offer evidence-based food-pattern education for long-term health while directing chest pressure, fainting, severe breathlessness, or stroke-like symptoms to urgent medical care.",activity:{prompt:"Which change most directly raises resistance in a small artery?",options:[{text:"A decrease in vessel radius",correct:true,feedback:"Correct. Narrowing greatly increases resistance to flow."},{text:"A larger capillary exchange area",correct:false,feedback:"Exchange area affects velocity and diffusion, not arteriolar radius directly."},{text:"Opening an atrioventricular valve",correct:false,feedback:"That changes intracardiac flow, not small-artery resistance."}]}}
    ]}
  ],
  caseStudy:{title:"A number, a symptom, and two different priorities",scenario:"A client wants nutrition advice after a home blood-pressure reading. During the conversation they also mention new chest pressure while climbing stairs. They ask whether simply avoiding salt for a week will settle both concerns.",prompts:["Which information belongs to long-term cardiovascular risk education?","Why can one home reading not define the mechanism?","Which symptom changes the priority of the conversation?","How can you state the nutrition role without delaying appropriate assessment?"],takeaway:"Nutrition can support long-term cardiovascular health, but new exertional chest pressure requires prompt medical assessment. Do not let risk-factor counselling become a substitute for symptom triage."},
  recap:["The right and left heart are pumps in series.","Valves open and close in response to pressure gradients.","The conduction system coordinates atrial and ventricular activation.","Diastole fills and systole ejects.","Arteries, veins, and capillaries have structure matched to function.","Distinct circulation routes serve lungs, myocardium, body tissues, and liver processing.","Perfusion integrates pump performance, vessel resistance, volume, and tissue demand."],
  flashcards:[{front:"Myocardium",back:"The contractile cardiac-muscle layer of the heart wall.",tag:"structure"},{front:"Endocardium",back:"The smooth inner lining of heart chambers and valves.",tag:"structure"},{front:"Tricuspid valve",back:"The right atrioventricular valve between right atrium and ventricle.",tag:"flow"},{front:"Mitral valve",back:"The left atrioventricular valve between left atrium and ventricle.",tag:"flow"},{front:"SA node",back:"The usual pacemaker that initiates atrial depolarization.",tag:"conduction"},{front:"AV node",back:"The conduction site that briefly delays the impulse before ventricular activation.",tag:"conduction"},{front:"Stroke volume",back:"The amount of blood ejected by one ventricle per beat.",tag:"cycle"},{front:"Cardiac output",back:"Heart rate multiplied by stroke volume; flow per minute.",tag:"cycle"},{front:"Arteriole",back:"A small resistance vessel that regulates flow into capillary beds.",tag:"vessels"},{front:"Capillary",back:"A microscopic thin-walled vessel specialized for exchange.",tag:"vessels"},{front:"Hepatic portal circulation",back:"Route carrying blood from digestive capillaries to liver sinusoids before systemic return.",tag:"routes"},{front:"Coronary circulation",back:"Blood supply serving the myocardium itself.",tag:"routes"}],
  practice:[{prompt:"Trace blood from the venae cavae to the aorta.",answer:"Right atrium → tricuspid valve → right ventricle → pulmonary valve → pulmonary trunk/arteries → lung capillaries → pulmonary veins → left atrium → mitral valve → left ventricle → aortic valve → aorta.",rationale:"The trace includes both pumps and pulmonary exchange.",tag:"flow"},{prompt:"Why is the left ventricular wall thicker?",answer:"It generates the higher pressure needed for systemic circulation.",rationale:"Wall thickness reflects workload, not oxygen content.",tag:"structure"},{prompt:"Put the conduction pathway in order.",answer:"SA node → AV node → AV bundle → bundle branches → Purkinje fibres.",rationale:"The order coordinates atria before ventricles.",tag:"conduction"},{prompt:"What usually closes the AV valves?",answer:"Ventricular pressure rising above atrial pressure.",rationale:"Valves respond passively to pressure gradients.",tag:"cycle"},{prompt:"Calculate cardiac output at 70 beats/min and 70 mL/beat.",answer:"4,900 mL/min, or 4.9 L/min.",rationale:"Cardiac output = heart rate × stroke volume.",tag:"cycle"},{prompt:"What defines an artery?",answer:"It carries blood away from the heart.",rationale:"Oxygen content does not define vessel type.",tag:"vessels"},{prompt:"Why do capillaries support exchange?",answer:"They have very thin walls, extensive area, and slow network flow.",rationale:"These features shorten diffusion distance and allow contact time.",tag:"vessels"},{prompt:"What is the purpose of the hepatic portal route?",answer:"It delivers blood from digestive organs to the liver before general systemic return.",rationale:"The liver can process absorbed water-soluble substances first.",tag:"routes"},{prompt:"Name four determinants in the PPVD perfusion model.",answer:"Pump, pipes, volume, and tissue demand.",rationale:"Perfusion is not explained by heart rate alone.",tag:"integration"},{prompt:"Why should new chest pressure not be handled with food advice alone?",answer:"It may signal an urgent cardiovascular problem requiring medical assessment.",rationale:"Long-term nutrition support must not delay acute symptom evaluation.",tag:"practice"}]
};
